    [AttributeUsage(AttributeTargets.Property)]
    public sealed class DataAttributeAttribute : Attribute
    {
        public DataAttributeAttribute() { }

        public DataAttributeAttribute(string param)
        {
            Parameter = param;
        }

        public string Parameter;
    }
}
